\set ON_ERROR_STOP on
SET ROLE hospital_owner;
SET search_path=pg_catalog,ext,public;
BEGIN;
CREATE TABLE ehr.encounter(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,patient_id bigint NOT NULL REFERENCES mpi.patient,type_code text NOT NULL REFERENCES ref.encounter_type,department_id bigint NOT NULL REFERENCES org.department,attending_staff_id bigint NOT NULL REFERENCES org.staff,status text NOT NULL CHECK(status IN('planned','in-progress','finished','cancelled')),started_at timestamptz NOT NULL,ended_at timestamptz,chief_complaint text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),row_version bigint NOT NULL DEFAULT 1,UNIQUE(id,patient_id),CHECK(ended_at IS NULL OR ended_at>started_at),CHECK(status<>'finished' OR ended_at IS NOT NULL),CHECK(status<>'in-progress' OR ended_at IS NULL));
CREATE TABLE ehr.encounter_participant(encounter_id bigint NOT NULL REFERENCES ehr.encounter,staff_id bigint NOT NULL REFERENCES org.staff,role_code text NOT NULL,participation_period tstzrange NOT NULL CHECK(NOT isempty(participation_period)),PRIMARY KEY(encounter_id,staff_id,role_code));
CREATE TABLE ehr.condition(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint,concept_id integer NOT NULL REFERENCES ref.concept,clinical_status text NOT NULL CHECK(clinical_status IN('active','resolved','remission')),verification_status text NOT NULL CHECK(verification_status IN('provisional','confirmed','refuted')),onset_at timestamptz NOT NULL,abatement_at timestamptz,rank smallint CHECK(rank>0),recorded_by bigint NOT NULL REFERENCES org.staff,FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id),CHECK(abatement_at IS NULL OR abatement_at>=onset_at));
CREATE TABLE ehr.allergy(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,substance_concept_id integer NOT NULL REFERENCES ref.concept,clinical_status text NOT NULL CHECK(clinical_status IN('active','inactive','resolved')),verification_status text NOT NULL CHECK(verification_status IN('unconfirmed','confirmed','refuted')),criticality text NOT NULL CHECK(criticality IN('low','high','unable-to-assess')),reaction_text text,recorded_at timestamptz NOT NULL,recorded_by bigint NOT NULL REFERENCES org.staff);
CREATE TABLE ehr.observation(id bigint GENERATED BY DEFAULT AS IDENTITY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,test_id integer NOT NULL REFERENCES ref.test,observed_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('preliminary','final','amended','entered-in-error')),value_numeric numeric(18,4),value_text text,value_concept_id integer REFERENCES ref.concept,value_boolean boolean,unit_code text REFERENCES ref.unit,recorded_by bigint NOT NULL REFERENCES org.staff,PRIMARY KEY(id,observed_at),FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id),CHECK(num_nonnulls(value_numeric,value_text,value_concept_id,value_boolean)=1),CHECK(value_numeric IS NULL OR unit_code IS NOT NULL)) PARTITION BY RANGE(observed_at);
DO $$DECLARE y int; m int; a date; b date; BEGIN FOR y IN 2024..2027 LOOP FOR m IN 1..12 LOOP a:=make_date(y,m,1); b:=(a+interval '1 month')::date; EXECUTE format('CREATE TABLE ehr.observation_%s PARTITION OF ehr.observation FOR VALUES FROM (%L) TO (%L)',to_char(a,'YYYY_MM'),a::text||' 00:00:00+05',b::text||' 00:00:00+05'); END LOOP; END LOOP; END$$;
CREATE TABLE ehr.procedure(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,service_id integer NOT NULL REFERENCES ref.service,status text NOT NULL CHECK(status IN('preparation','in-progress','completed','not-done')),performed_period tstzrange NOT NULL CHECK(NOT isempty(performed_period)),performer_id bigint NOT NULL REFERENCES org.staff,outcome_text text,FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE ehr.clinical_note(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,note_type text NOT NULL CHECK(note_type IN('progress','consultation','discharge','nursing')),author_id bigint NOT NULL REFERENCES org.staff,created_at timestamptz NOT NULL,current_version integer NOT NULL DEFAULT 1 CHECK(current_version>0),UNIQUE(id,patient_id),FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE ehr.note_version(note_id bigint NOT NULL REFERENCES ehr.clinical_note,version integer NOT NULL CHECK(version>0),body ref.nonblank_text NOT NULL,created_at timestamptz NOT NULL,author_id bigint NOT NULL REFERENCES org.staff,signed_at timestamptz,signed_by bigint REFERENCES org.staff,supersedes_version integer,amendment_reason text,body_sha256 bytea GENERATED ALWAYS AS(ext.digest(body,'sha256')) STORED,PRIMARY KEY(note_id,version),FOREIGN KEY(note_id,supersedes_version) REFERENCES ehr.note_version(note_id,version),CHECK((signed_at IS NULL)=(signed_by IS NULL)),CHECK(signed_at IS NULL OR signed_at>=created_at),CHECK((version=1 AND supersedes_version IS NULL) OR (version>1 AND supersedes_version=version-1 AND amendment_reason IS NOT NULL)));
ALTER TABLE ehr.clinical_note ADD CONSTRAINT note_current_version_fk FOREIGN KEY(id,current_version) REFERENCES ehr.note_version(note_id,version) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE ehr.care_plan(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint,status text NOT NULL CHECK(status IN('draft','active','completed','revoked')),title text NOT NULL,valid_during tstzrange NOT NULL CHECK(NOT isempty(valid_during)),author_id bigint NOT NULL REFERENCES org.staff,UNIQUE(id,patient_id),FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE ehr.care_plan_activity(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,care_plan_id bigint NOT NULL REFERENCES ehr.care_plan,service_id integer NOT NULL REFERENCES ref.service,status text NOT NULL CHECK(status IN('scheduled','in-progress','completed','cancelled')),scheduled_at timestamptz NOT NULL,assigned_staff_id bigint REFERENCES org.staff);
CREATE TABLE ehr.document(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint,document_type text NOT NULL,storage_uri text NOT NULL UNIQUE,media_type text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>0),sha256 bytea NOT NULL CHECK(octet_length(sha256)=32),created_at timestamptz NOT NULL,author_id bigint NOT NULL REFERENCES org.staff,FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE ehr.death_record(patient_id bigint PRIMARY KEY REFERENCES mpi.patient,encounter_id bigint,death_at timestamptz NOT NULL,certified_by bigint NOT NULL REFERENCES org.staff,cause_concept_id integer REFERENCES ref.concept,certificate_number text NOT NULL UNIQUE,FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE ehr.immunization(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,vaccine_concept_id integer NOT NULL REFERENCES ref.concept,occurred_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('completed','not-done','entered-in-error')),lot_number text,performer_id bigint NOT NULL REFERENCES org.staff,FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE adt.admission(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL UNIQUE,admission_number text NOT NULL UNIQUE,admitted_at timestamptz NOT NULL,discharged_at timestamptz,admission_source text NOT NULL CHECK(admission_source IN('emergency','referral','transfer')),UNIQUE(id,patient_id),FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id),CHECK(discharged_at IS NULL OR discharged_at>admitted_at),EXCLUDE USING gist(patient_id WITH =,tstzrange(admitted_at,discharged_at,'[)') WITH &&));
CREATE TABLE adt.bed_stay(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,admission_id bigint NOT NULL,patient_id bigint NOT NULL,bed_id bigint NOT NULL REFERENCES org.bed,occupied_during tstzrange NOT NULL CHECK(NOT isempty(occupied_during) AND NOT lower_inf(occupied_during) AND lower_inc(occupied_during) AND NOT upper_inc(occupied_during)),FOREIGN KEY(admission_id,patient_id) REFERENCES adt.admission(id,patient_id),EXCLUDE USING gist(bed_id WITH =,occupied_during WITH &&),EXCLUDE USING gist(patient_id WITH =,occupied_during WITH &&));
CREATE TABLE adt.discharge(admission_id bigint PRIMARY KEY,patient_id bigint NOT NULL,discharged_at timestamptz NOT NULL,disposition text NOT NULL CHECK(disposition IN('home','transfer','deceased','other')),summary_note_id bigint NOT NULL,approved_by bigint NOT NULL REFERENCES org.staff,FOREIGN KEY(admission_id,patient_id) REFERENCES adt.admission(id,patient_id),FOREIGN KEY(summary_note_id,patient_id) REFERENCES ehr.clinical_note(id,patient_id));
CREATE TABLE scheduling.schedule(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,staff_id bigint NOT NULL REFERENCES org.staff,department_id bigint NOT NULL REFERENCES org.department,valid_during daterange NOT NULL CHECK(NOT isempty(valid_during)),active boolean NOT NULL DEFAULT true,UNIQUE(id,staff_id,department_id));
CREATE TABLE scheduling.slot(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,schedule_id bigint NOT NULL,staff_id bigint NOT NULL,department_id bigint NOT NULL,room_id bigint NOT NULL,slot_period tstzrange NOT NULL CHECK(NOT isempty(slot_period) AND NOT lower_inf(slot_period) AND NOT upper_inf(slot_period) AND lower_inc(slot_period) AND NOT upper_inc(slot_period)),status text NOT NULL CHECK(status IN('free','busy','blocked')),FOREIGN KEY(schedule_id,staff_id,department_id) REFERENCES scheduling.schedule(id,staff_id,department_id),FOREIGN KEY(room_id,department_id) REFERENCES org.room(id,department_id),EXCLUDE USING gist(staff_id WITH =,slot_period WITH &&),EXCLUDE USING gist(room_id WITH =,slot_period WITH &&));
CREATE TABLE scheduling.appointment(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,slot_id bigint NOT NULL UNIQUE REFERENCES scheduling.slot,service_id integer NOT NULL REFERENCES ref.service,status text NOT NULL CHECK(status IN('booked','arrived','fulfilled','cancelled','noshow')),created_at timestamptz NOT NULL,encounter_id bigint,reason_text text,FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE scheduling.appointment_participant(appointment_id bigint NOT NULL REFERENCES scheduling.appointment,staff_id bigint NOT NULL REFERENCES org.staff,status text NOT NULL CHECK(status IN('accepted','tentative','declined')),PRIMARY KEY(appointment_id,staff_id));
CREATE TABLE lab.service_request(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,service_id integer NOT NULL REFERENCES ref.service,panel_id integer REFERENCES ref.test_panel,ordered_by bigint NOT NULL REFERENCES org.staff,ordered_at timestamptz NOT NULL,priority text NOT NULL CHECK(priority IN('routine','urgent','stat')),status text NOT NULL CHECK(status IN('draft','active','completed','cancelled')),UNIQUE(id,patient_id),FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE lab.specimen(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,accession_number text NOT NULL UNIQUE,type_code text NOT NULL,collected_at timestamptz NOT NULL,received_at timestamptz,status text NOT NULL CHECK(status IN('available','unavailable','unsatisfactory')),collected_by bigint NOT NULL REFERENCES org.staff,UNIQUE(id,patient_id),CHECK(received_at IS NULL OR received_at>=collected_at));
CREATE TABLE lab.request_specimen(request_id bigint NOT NULL,specimen_id bigint NOT NULL,patient_id bigint NOT NULL,PRIMARY KEY(request_id,specimen_id),FOREIGN KEY(request_id,patient_id) REFERENCES lab.service_request(id,patient_id),FOREIGN KEY(specimen_id,patient_id) REFERENCES lab.specimen(id,patient_id));
CREATE TABLE lab.diagnostic_report(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,request_id bigint NOT NULL,status text NOT NULL CHECK(status IN('preliminary','final','amended','entered-in-error')),issued_at timestamptz NOT NULL,verified_by bigint NOT NULL REFERENCES org.staff,conclusion_text text,version integer NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(id,patient_id),UNIQUE(request_id,version),FOREIGN KEY(request_id,patient_id) REFERENCES lab.service_request(id,patient_id));
CREATE TABLE lab.result(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,specimen_id bigint NOT NULL,test_id integer NOT NULL REFERENCES ref.test,measured_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('preliminary','final','amended')),value_numeric numeric(18,4),value_text text,unit_code text REFERENCES ref.unit,reference_low numeric(18,4),reference_high numeric(18,4),interpretation text CHECK(interpretation IN('N','L','H','critical','not-applicable')),analyzer_id bigint REFERENCES org.device,UNIQUE(id,patient_id),FOREIGN KEY(specimen_id,patient_id) REFERENCES lab.specimen(id,patient_id),CHECK(num_nonnulls(value_numeric,value_text)=1),CHECK(value_numeric IS NULL OR unit_code IS NOT NULL),CHECK(reference_low IS NULL OR reference_high IS NULL OR reference_low<=reference_high));
CREATE TABLE lab.report_result(report_id bigint NOT NULL,result_id bigint NOT NULL,patient_id bigint NOT NULL,PRIMARY KEY(report_id,result_id),FOREIGN KEY(report_id,patient_id) REFERENCES lab.diagnostic_report(id,patient_id),FOREIGN KEY(result_id,patient_id) REFERENCES lab.result(id,patient_id));
CREATE TABLE imaging.imaging_order(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,encounter_id bigint NOT NULL,service_id integer NOT NULL REFERENCES ref.service,requested_at timestamptz NOT NULL,requested_by bigint NOT NULL REFERENCES org.staff,status text NOT NULL CHECK(status IN('active','completed','cancelled')),UNIQUE(id,patient_id),FOREIGN KEY(encounter_id,patient_id) REFERENCES ehr.encounter(id,patient_id));
CREATE TABLE imaging.study(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id bigint NOT NULL REFERENCES mpi.patient,order_id bigint NOT NULL,study_instance_uid text NOT NULL UNIQUE,accession_number text NOT NULL UNIQUE,modality text NOT NULL CHECK(modality IN('CT','MR','US','DX')),started_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('registered','available','cancelled')),device_id bigint NOT NULL REFERENCES org.device,report_text text,FOREIGN KEY(order_id,patient_id) REFERENCES imaging.imaging_order(id,patient_id));
CREATE TABLE imaging.series(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,study_id bigint NOT NULL REFERENCES imaging.study,series_instance_uid text NOT NULL UNIQUE,series_number integer NOT NULL CHECK(series_number>0),instance_count integer NOT NULL CHECK(instance_count>=0),storage_uri text NOT NULL,UNIQUE(study_id,series_number));
INSERT INTO ops.schema_migration VALUES('02',clock_timestamp(),'Clinical record, ADT, scheduling, laboratory and imaging');
COMMIT;
